using System.Collections.Generic;
using System.Reflection;
using System.Threading;
using System.Web.Script.Serialization;
namespace PZ3D {
 static class ModConfigurationsTests {
  static Type Api;static int assertions,failures;
  static readonly string TestRoot=Path.Combine(LauncherTestPaths.Root,"mod-workspace-fixtures");
  sealed class Fixture {
   public string Root;public Engine E;
   public Fixture(){Root=Path.Combine(TestRoot,Guid.NewGuid().ToString("N"));E=new Engine(Path.Combine(Root,"steamapps/common/ProjectZomboid"),Path.Combine(Root,"User"),Path.Combine(Root,"Data"),true);Put(E.Config,"{\"vmArgs\":[]}");Put(Path.Combine(E.Game,"game-version.txt"),"42.12.3");Mod("A","");Mod("B","require=A\n");Put(E.Mods,Text(new[]{"A","B"}));}
   public void Mod(string id,string extra){Put(Path.Combine(E.User,"mods",id.Replace('/','_').Replace('\\','_'),"42/mod.info"),"id="+id+"\nname=Title "+id+"\nauthor=Original author\nmodversion=1.2\ndescription=Original description\n"+extra);}
  }
  static void Put(string path,string value){Directory.CreateDirectory(Path.GetDirectoryName(path));File.WriteAllText(path,value,new UTF8Encoding(false));}
  static string Text(string[] mods){return "VERSION = 1,\r\nmods\r\n{\r\n"+string.Concat(mods.Select(id=>"    mod = "+id+",\r\n"))+"}\r\nmaps\r\n{\r\n    map = Muldraugh, KY,\r\n}\r\ncustom\r\n{\r\n    original = untouched,\r\n}\r\n";}
  static void Check(bool value,string label){assertions++;if(!value)throw new Exception("FAIL: "+label);}
  static object Call(string method,params object[] args){Check(Api!=null,"named configuration API exists");var member=Api.GetMethod(method);Check(member!=null,"named configuration method "+method+" exists");try{return member.Invoke(null,args);}catch(TargetInvocationException x){throw x.InnerException;}}
  static Dictionary<string,object> D(object value){var json=new JavaScriptSerializer{MaxJsonLength=2097152};return json.Deserialize<Dictionary<string,object>>(json.Serialize(value));}
  static object[] Rows(Dictionary<string,object> d,string key){return ((ArrayList)d[key]).Cast<object>().ToArray();}
  static string[] Strings(Dictionary<string,object> d,string key){return Rows(d,key).Select(x=>x.ToString()).ToArray();}
  static string Stamp(Engine e){return (string)D(Call("List",e))["stamp"];}
  static Dictionary<string,object> Save(Engine e,string name,string[] mods,string id=null,string stamp=null){return D(Call("Save",e,new Dictionary<string,object>{{"id",id},{"name",name},{"mods",mods},{"stamp",stamp??Stamp(e)}}));}
  static void Refuses(Action work,string label){bool refused=false;try{work();}catch{refused=true;}Check(refused,label);}
  static void Case(string name,Action work){try{work();Console.WriteLine("PASS "+name);}catch(Exception x){failures++;Console.WriteLine("FAIL "+name+": "+x.Message);}}
  public static int Main(){try{Run();return 0;}catch(Exception x){Console.WriteLine(x.Message);return 1;}}
  public static void Run(){assertions=failures=0;Api=typeof(Engine).Assembly.GetType("PZ3D.ModConfigurations");
   Case("catalog soft edges and original metadata",Catalog);
   Case("persistent named drafts separate from saves",Profiles);
   Case("stale and concurrent collection writes",Stale);
   Case("activation preserves blocks and managed components",Activation);
   Case("stable dependency preview and errors",Sorting);
   Case("guards and confined opaque IDs",Guards);
   Case("corrupt and reparsed collection refusal",Corrupt);
   Case("absent default and unfamiliar syntax",AbsentDefault);
   Case("B42 qualified hard dependencies and managed bridge",B42Requires);
   Case("game loadModAfter/loadModBefore soft-order aliases",B42SoftEdges);
   Console.WriteLine("ModConfigurations: "+assertions+" assertions, "+failures+" failed cases; fixtures "+TestRoot);
   if(failures!=0)throw new Exception("Mod workspace tests failed: "+failures);
  }
  static void Catalog(){var f=new Fixture();f.Mod("Soft","loadAfter= A ; B\nloadBefore= Other, Another\nconflicts=Block\ncustomOriginal=Keep this source value\n");var rows=Rows(D(SaveProfiles.Catalog(f.E)),"mods").Select(D).ToArray();var row=rows.Single(x=>(string)x["id"]=="Soft");Check(row.ContainsKey("loadAfter")&&Strings(row,"loadAfter").SequenceEqual(new[]{"A","B"}),"catalog parses author loadAfter");Check(Strings(row,"loadBefore").SequenceEqual(new[]{"Other","Another"}),"catalog parses author loadBefore");Check(Strings(row,"conflicts").SequenceEqual(new[]{"Block"}),"catalog parses conflicts");Check((string)row["title"]=="Title Soft"&&(string)row["item"]=="","catalog supplies title/item aliases");Check((string)D(row["metadata"])["customOriginal"]=="Keep this source value","catalog keeps original author metadata");Check(Strings(rows.Single(x=>(string)x["id"]=="B"),"require").SequenceEqual(new[]{"A"}),"catalog require alias retains hard edges");}
  static void Profiles(){var f=new Fixture();byte[] before=File.ReadAllBytes(f.E.Mods);var list=D(Call("List",f.E));Check(Rows(list,"profiles").Length==0&&Strings(list,"activeMods").SequenceEqual(new[]{"A","B"}),"initial read exposes actual default without writes");Check(!Directory.Exists(f.E.Data),"read-only empty collection creates no files");var saved=Save(f.E," My profile ",new[]{"B","A"});string id=(string)saved["id"];Check(id.Length==32&&id.All(c=>"0123456789abcdef".Contains(c)),"profile opaque generated ID");Check((string)saved["name"]=="My profile"&&Strings(saved,"mods").SequenceEqual(new[]{"B","A"}),"draft keeps chosen order for editing");var other=new Engine(f.E.Game,f.E.User,f.E.Data,true);var read=D(Call("Read",other,id));Check(Strings(read,"mods").SequenceEqual(new[]{"B","A"}),"another engine reads persistent profile");var row=D(Rows(D(Call("List",other)),"profiles").Single());Check((string)row["name"]=="My profile"&&Convert.ToInt32(row["modCount"])==2&&row.ContainsKey("updated"),"collection summary shape");Save(other,"Renamed",new[]{"A","B"},id,(string)read["stamp"]);Check(Rows(D(Call("List",f.E)),"profiles").Length==1,"edit updates one existing identity");Check(File.ReadAllBytes(f.E.Mods).SequenceEqual(before)&&!Directory.Exists(Path.Combine(f.E.User,"Saves")),"draft never changes defaults or saves");Call("Delete",f.E,id,Stamp(f.E));Check(Rows(D(Call("List",f.E)),"profiles").Length==0,"delete persists collection removal");Refuses(()=>Call("Read",f.E,id),"deleted profile unavailable");}
  static void Stale(){var f=new Fixture();string initial=Stamp(f.E);var first=Save(f.E,"First",new[]{"A"},null,initial);Refuses(()=>Save(f.E,"Stale",new[]{"A"},null,initial),"creation refuses stale collection");Refuses(()=>Call("Delete",f.E,(string)first["id"],initial),"delete refuses stale collection");Refuses(()=>Save(f.E,"Missing stamp",new[]{"A"},null,""),"collection stamp required even create");string stamp=Stamp(f.E);Put(f.E.Mods,Text(new[]{"A"}));Refuses(()=>Call("Activate",f.E,(string)first["id"],stamp,true),"external default edit makes activation stale");stamp=Stamp(f.E);int success=0,refused=0;Exception unexpected=null;var start=new ManualResetEvent(false);ThreadStart writer=()=>{start.WaitOne();try{Save(f.E,"Parallel",new[]{"A"},null,stamp);Interlocked.Increment(ref success);}catch(Exception x){if(x.Message.Contains("修改")||x.Message.Contains("配置"))Interlocked.Increment(ref refused);else unexpected=x;}};var a=new Thread(writer);var b=new Thread(writer);a.Start();b.Start();start.Set();a.Join();b.Join();if(unexpected!=null)throw unexpected;Check(success==1&&refused==1,"same stamp parallel writers produce one complete write");Check(Rows(D(Call("List",f.E)),"profiles").Length==2,"concurrent refused write leaves winning collection intact");Check(!Directory.GetFiles(f.E.Data,"*.tmp",SearchOption.AllDirectories).Any(),"atomic profile write cleans temporary file");}
  static void Activation(){var f=new Fixture();f.Mod("Viewpoint","require=ZombieBuddy\n");f.Mod(ShootClient.Id,"require=Viewpoint\n");f.Mod("ViewpointSurface","require=Viewpoint\n");Put(f.E.Config,"{\"vmArgs\":[\"-agentlib:zbNative\"]}");Put(Path.Combine(f.E.Game,"ZombieBuddy.jar"),"synthetic binary");Put(Path.Combine(f.E.Game,"zbNative.dll"),"synthetic binary");string original=Text(new[]{"ZombieBuddy","Viewpoint",ShootClient.Id,"ViewpointSurface","A","B"});File.WriteAllText(f.E.Mods,original,new UTF8Encoding(true));var preview=D(Call("Sort",f.E,new[]{"ZombieBuddy","Viewpoint",ShootClient.Id,"ViewpointSurface","A","B"}));Check(Strings(preview,"errors").Length==0,"preview respects current verified loader-only Buddy");var saved=Save(f.E,"Activate",new[]{"A"});string id=(string)saved["id"],stamp=(string)saved["stamp"];byte[] before=File.ReadAllBytes(f.E.Mods);Refuses(()=>Call("Activate",f.E,id,stamp,false),"activation requires explicit confirmation");Check(before.SequenceEqual(File.ReadAllBytes(f.E.Mods)),"unconfirmed activation leaves defaults");Call("Activate",f.E,id,stamp,true);var list=D(Call("List",f.E));Check(Strings(list,"activeMods").SequenceEqual(new[]{"A"})&&SaveProfiles.DefaultMods(File.ReadAllBytes(f.E.Mods)).SequenceEqual(new[]{"ZombieBuddy","Viewpoint",ShootClient.Id,"ViewpointSurface","A"}),"activation preserves managed active components including loader-only Buddy");byte[] output=File.ReadAllBytes(f.E.Mods);Check(output.Take(3).SequenceEqual(new byte[]{239,187,191}),"activation keeps BOM");Check(File.ReadAllText(f.E.Mods).Contains("maps\r\n{\r\n    map = Muldraugh, KY,\r\n}\r\ncustom\r\n{\r\n    original = untouched,\r\n}"),"activation keeps maps/custom byte layout");Check(!Directory.Exists(Path.Combine(f.E.User,"Saves")),"activation never creates saves");var wrong=Save(f.E,"Wrong order",new[]{"B","A"});before=File.ReadAllBytes(f.E.Mods);Call("Activate",f.E,(string)wrong["id"],(string)wrong["stamp"],true);Check(SaveProfiles.DefaultMods(File.ReadAllBytes(f.E.Mods)).SequenceEqual(new[]{"ZombieBuddy","Viewpoint",ShootClient.Id,"ViewpointSurface","A","B"}),"activation automatically orders the final combined list");before=File.ReadAllBytes(f.E.Mods);var missing=Save(f.E,"Missing",new[]{"Absent"});Refuses(()=>Call("Activate",f.E,(string)missing["id"],(string)missing["stamp"],true),"activation refuses missing local mod");Check(before.SequenceEqual(File.ReadAllBytes(f.E.Mods)),"dependency refusals do not overwrite defaults");Check(Directory.GetFiles(f.E.Data,"default.txt",SearchOption.AllDirectories).Any(),"activation retains original default backup");}
  static void Sorting(){var f=new Fixture();f.Mod("Independent","");f.Mod("Soft","loadAfter=A\nloadBefore=B\n");byte[] before=File.ReadAllBytes(f.E.Mods);var sorted=D(Call("Sort",f.E,new[]{"B","Independent","Soft","A"}));Check(Strings(sorted,"mods").SequenceEqual(new[]{"Independent","A","Soft","B"})&&Convert.ToBoolean(sorted["changed"]),"stable Kahn respects hard and selected soft edges");Check(Strings(sorted,"errors").Length==0,"valid preview has no dependency errors");var stable=D(Call("Sort",f.E,new[]{"Independent","A","Soft","B"}));Check(!Convert.ToBoolean(stable["changed"]),"valid independent order is unchanged");var trimmed=D(Call("Sort",f.E,new[]{" Independent "}));Check(Strings(trimmed,"mods").SequenceEqual(new[]{"Independent"})&&Convert.ToBoolean(trimmed["changed"]),"preview changed reflects ID whitespace normalization");var unselected=D(Call("Sort",f.E,new[]{"Soft"}));Check(Strings(unselected,"errors").Length==0,"unselected soft edges impose no requirements");Check(Strings(D(Call("Sort",f.E,new[]{"B"})),"errors").Length>0,"unselected hard dependency is error");Check(Strings(D(Call("Sort",f.E,new[]{"Missing"})),"errors").Length>0,"missing local ID is error");Check(Strings(D(Call("Sort",f.E,new[]{"A","A"})),"errors").Length>0,"duplicate selected IDs are error");f.Mod("CycleA","require=CycleB\n");f.Mod("CycleB","loadAfter=CycleA\n");var cycle=D(Call("Sort",f.E,new[]{"CycleB","CycleA"}));Check(Strings(cycle,"errors").Length>0&&Strings(cycle,"mods").SequenceEqual(new[]{"CycleB","CycleA"}),"cycles report error and retain original preview list");f.Mod("Conflict","conflicts=A\n");Check(Strings(D(Call("Sort",f.E,new[]{"A","Conflict"})),"errors").Length>0,"author conflict with selected mod is error");Put(Path.Combine(f.E.Workshop,"123/mods/Dup/42/mod.info"),"id=A\n");Check(Strings(D(Call("Sort",f.E,new[]{"A"})),"errors").Length>0,"duplicate local source is error");Check(File.ReadAllBytes(f.E.Mods).SequenceEqual(before)&&!Directory.Exists(f.E.Data),"sort is preview only and never writes");f.Mod("Opaque/中文","loadAfter=Independent\n");var opaque=D(Call("Sort",f.E,new[]{"Opaque/中文","Independent"}));Check(Strings(opaque,"mods").SequenceEqual(new[]{"Independent","Opaque/中文"}),"mod IDs are opaque metadata values, not paths");}
  static void Guards(){var f=new Fixture();var p=Save(f.E,"Guard",new[]{"A"});byte[] before=File.ReadAllBytes(f.E.Mods);foreach(string bad in new[]{"../outside","A/B",new string('a',64),"CON",(string)p["id"]+" "}){Refuses(()=>Call("Read",f.E,bad),"invalid profile read identity refused");Refuses(()=>Call("Delete",f.E,bad,Stamp(f.E)),"invalid profile delete identity refused");Refuses(()=>Call("Activate",f.E,bad,Stamp(f.E),true),"invalid profile activation identity refused");}Refuses(()=>Save(f.E,"Bad",new[]{"injected\nmod = Evil,"}),"INI injection is not a profile mod ID");Refuses(()=>Save(f.E,"\u0001name",new[]{"A"}),"profile name control characters refused");string journal=Path.Combine(f.E.Data,"launch-sessions",LaunchProfiles.Key(f.E)+".json");Put(journal,"synthetic pending session");var pending=Save(f.E,"Pending",new[]{"A"});Call("Delete",f.E,(string)pending["id"],Stamp(f.E));Check(Strings(D(Call("Read",f.E,(string)p["id"])),"mods").Single()=="A","pending session permits draft save/delete/read");Call("Activate",f.E,(string)p["id"],Stamp(f.E),true);Check(Strings(D(Call("List",f.E)),"activeMods").SequenceEqual(new[]{"A"}),"pending session permits confirmed default editing");File.Delete(journal);Put(Path.Combine(f.E.Game,"ProjectZomboid64.bat"),"SET _JAVA_OPTIONS=-agentlib:zbNative");before=File.ReadAllBytes(f.E.Mods);Call("Activate",f.E,(string)p["id"],Stamp(f.E),true);f.E.Guard();Check(File.ReadAllText(Path.Combine(f.E.Game,"ProjectZomboid64.bat"))=="SET _JAVA_OPTIONS=-agentlib:zbNative","unused BAT remains byte-identical after configuration guard");Save(f.E,"Guarded",new[]{"A"});Check(before.SequenceEqual(File.ReadAllBytes(f.E.Mods)),"named drafts and ordinary activation ignore unrelated BAT without altering selected membership");}
  static void Corrupt(){var f=new Fixture();Save(f.E,"Good",new[]{"A"});string file=Directory.GetFiles(f.E.Data,"*.json",SearchOption.AllDirectories).Single();byte[] original=File.ReadAllBytes(file);Put(file,"{not valid");Refuses(()=>Call("List",f.E),"corrupt collection is refused rather than reset");Check(File.ReadAllText(file)=="{not valid","read refuses without replacing corrupt collection");Put(file,"{}");Refuses(()=>Call("List",f.E),"missing collection schema cannot silently become empty");Put(file,"{\"version\":1}");Refuses(()=>Call("List",f.E),"missing profiles collection cannot silently become empty");File.WriteAllBytes(file,original);string directory=Path.GetDirectoryName(file),moved=Path.Combine(f.Root,"external-profile-store");Directory.Move(directory,moved);var process=System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo("cmd.exe","/c mklink /J \""+directory+"\" \""+moved+"\""){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true});process.WaitForExit();Check(process.ExitCode==0,"synthetic collection junction created");process.Dispose();Refuses(()=>Call("List",f.E),"collection reparse path refused");Check(File.ReadAllBytes(Path.Combine(moved,Path.GetFileName(file))).SequenceEqual(original),"reparse refusal never changes external bytes");}
  static void AbsentDefault(){var f=new Fixture();File.Delete(f.E.Mods);var p=Save(f.E,"Create default",new[]{"A"});Check(!File.Exists(f.E.Mods),"saving a draft never creates absent default");Call("Activate",f.E,(string)p["id"],(string)p["stamp"],true);Check(Strings(D(Call("List",f.E)),"activeMods").SequenceEqual(new[]{"A"})&&File.ReadAllText(f.E.Mods).Contains("maps\n{\n}"),"confirmed activation creates valid default when absent");Put(f.E.Mods,"VERSION = 1,\nmods\n{\n    mod = A,\n    unknown = untouched,\n}\nmaps\n{\n}\n");byte[] original=File.ReadAllBytes(f.E.Mods);Refuses(()=>Call("Activate",f.E,(string)p["id"],Stamp(f.E),true),"unfamiliar mods-block syntax refuses activation");Check(File.ReadAllBytes(f.E.Mods).SequenceEqual(original),"unfamiliar mods-block bytes preserved");}
  static void B42Requires(){var f=new Fixture();f.Mod("Viewpoint","require=\\ZombieBuddy\n");f.Mod(ShootClient.Id,"require=\\Viewpoint\n");f.Mod(PresentationBridge.Id,"require=\\ZombieBuddy,\\Viewpoint\nloadModAfter=Viewpoint,ShootToThrillMultiplayer\n");var row=Rows(D(SaveProfiles.Catalog(f.E)),"mods").Select(D).Single(x=>(string)x["id"]==PresentationBridge.Id);Check(Strings(row,"requires").SequenceEqual(new[]{"ZombieBuddy","Viewpoint"}),"B42 leading backslash qualifies dependencies rather than mod IDs");Check((string)D(row["metadata"])["require"]=="\\ZombieBuddy,\\Viewpoint","raw B42 dependency evidence stays unchanged");Put(f.E.Config,"{\"vmArgs\":[\"-agentlib:zbNative\"]}");Put(Path.Combine(f.E.Game,"ZombieBuddy.jar"),"synthetic binary");Put(Path.Combine(f.E.Game,"zbNative.dll"),"synthetic binary");string[] active={"ZombieBuddy","Viewpoint",ShootClient.Id,PresentationBridge.Id,"A","B"};Put(f.E.Mods,Text(active));var preview=D(Call("Sort",f.E,new[]{PresentationBridge.Id,ShootClient.Id,"Viewpoint","ZombieBuddy"}));Check(Strings(preview,"errors").Length==0&&Strings(preview,"mods").Length==0,"actual B42 managed dependencies sort against canonical active IDs");var saved=Save(f.E,"B42 ordinary draft",new[]{"A"});Call("Activate",f.E,(string)saved["id"],(string)saved["stamp"],true);Check(SaveProfiles.DefaultMods(File.ReadAllBytes(f.E.Mods)).SequenceEqual(new[]{"ZombieBuddy","Viewpoint",ShootClient.Id,"A"}),"activation excludes retired bridge while preserving B42 author components");Put(f.E.Mods,Text(new[]{"\\ZombieBuddy","\\Viewpoint","A"}));saved=Save(f.E,"Qualified current components",new[]{"A"});Call("Activate",f.E,(string)saved["id"],(string)saved["stamp"],true);Check(SaveProfiles.DefaultMods(File.ReadAllBytes(f.E.Mods)).SequenceEqual(new[]{"\\ZombieBuddy","\\Viewpoint","A"}),"qualified managed rows resolve canonical metadata and preserve spelling");}
  static void B42SoftEdges(){var f=new Fixture();f.Mod("SoftAfter","loadModAfter=A\n");var after=D(Call("Sort",f.E,new[]{"SoftAfter","A"}));Check(Strings(after,"mods").SequenceEqual(new[]{"A","SoftAfter"})&&Convert.ToBoolean(after["changed"]),"game loadModAfter creates selected soft edge");f.Mod("SoftBefore","loadModBefore=\\A\n");var before=D(Call("Sort",f.E,new[]{"A","SoftBefore"}));Check(Strings(before,"mods").SequenceEqual(new[]{"SoftBefore","A"}),"game loadModBefore supports qualified soft reference");var rows=Rows(D(SaveProfiles.Catalog(f.E)),"mods").Select(D).ToArray();var catalogAfter=rows.Single(x=>(string)x["id"]=="SoftAfter");var catalogBefore=rows.Single(x=>(string)x["id"]=="SoftBefore");Check(Strings(catalogAfter,"loadAfter").SequenceEqual(new[]{"A"})&&Strings(catalogBefore,"loadBefore").SequenceEqual(new[]{"A"}),"contract soft-edge fields expose native game key aliases");Check((string)D(catalogBefore["metadata"])["loadModBefore"]=="\\A","soft-order raw metadata remains source evidence");Check(Strings(D(Call("Sort",f.E,new[]{"SoftAfter"})),"errors").Length==0,"unselected game soft edge is optional");f.Mod("Opaque\\Value","");f.Mod("InternalSlash","require=Opaque\\Value\n");Check(Strings(D(Call("Sort",f.E,new[]{"InternalSlash","Opaque\\Value"})),"mods").SequenceEqual(new[]{"Opaque\\Value","InternalSlash"}),"dependency canonicalization does not alter embedded opaque backslashes");}
 }
